    },
    {
      "card_ids": ["C06"],
      "claim": "Rebamipide, an oral drug containing a carboxylic acid and aromatic heterocycle, has human bioavailability under 10%, supporting low F for the query's carboxylic-acid-containing heteroaromatic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "FK3453, a heteroaromatic drug with low oral bioavailability due to aldehyde oxidase-mediated clearance, illustrates that heteroaromatic azole-containing compounds can have unexpectedly poor oral F, relevant to the query's triazole core.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) based on consistent human low-F evidence for structurally related polyphenolic, heteroaromatic, and carboxylic-acid-containing drugs; no direct query PK data are available.",
